/bin/bash -lc "mkdir -p scripts && cat > scripts/inspect_rds.R <<'R'
args <- commandArgs(trailingOnly = TRUE)
if (length(args) < 3) {
  stop(\"usage: inspect_rds.R input.rds report.tsv metadata.tsv [member]\")
}
input_path <- args[[1]]
report_path <- args[[2]]
metadata_path <- args[[3]]
member <- if (length(args) >= 4 && nzchar(args[[4]])) args[[4]] else NULL

obj <- readRDS(input_path)

class_str <- function(x) paste(class(x), collapse = \",\")
dim_str <- function(x) {
  d <- dim(x)
  if ("'!is.null(d)) return(paste(d, collapse = "x"))
  paste(length(x), collapse = "x")
}
type_str <- function(x) {
  if (isS4(x)) paste0("S4:", class_str(x)) else typeof(x)
}

emit <- function(label, x) {
  cat(label, "'"\\t\", type_str(x), \"\\t\", class_str(x), \"\\t\", dim_str(x), \"\\n\", sep = \"\", file = report_path, append = TRUE)
}

file.create(report_path)
emit(\"__root__\", obj)

if (isS4(obj)) {
  for (s in slotNames(class(obj))) {
    val <- tryCatch(slot(obj, s), error = function(e) NULL)
    if ("'!is.null(val)) emit(paste0("@", s), val)
  }
}
if (is.list(obj) || is.environment(obj)) {
  nms <- names(obj)
  if (!is.null(nms)) {
    for (n in nms) {
      val <- tryCatch(obj[[n]], error = function(e) NULL)
      if (!is.null(val)) emit(paste0("$", n), val)
    }
  }
}

extract_member <- function(member) {
  if (startsWith(member, "@")) {
    nm <- substring(member, 2)
    if (isS4(obj) && nm %in% slotNames(class(obj))) return(slot(obj, nm))
  } else if (startsWith(member, "$")) {
    nm <- substring(member, 2)
    if ((is.list(obj) || is.environment(obj)) && nm %in% names(obj)) return(obj[[nm]])
  } else {
    if (is.list(obj) || is.environment(obj)) {
      nms <- names(obj)
      if (!is.null(nms) && member %in% nms) return(obj[[member]])
    }
    if (isS4(obj) && member %in% slotNames(class(obj))) return(slot(obj, member))
  }
  stop("member not found: ", member)
}

if (is.null(member)) {
  writeLines("no_member_requested", metadata_path)
} else {
  sel <- extract_member(member)
  if (is.data.frame(sel)) {
    df <- sel
  } else if (is.matrix(sel) || inherits(sel, "Matrix")) {
    df <- as.data.frame(as.matrix(sel), stringsAsFactors = FALSE)
  } else if (is.list(sel)) {
    lens <- vapply(sel, length, integer(1))
    if (length(unique(lens)) != 1) stop("list member has unequal lengths")
    df <- as.data.frame(sel, stringsAsFactors = FALSE)
  } else {
    stop("selected member cannot be converted to a table: ", class_str(sel))
  }
  if (!is.null(rownames(df)) && !all(rownames(df) == as.character(seq_len(nrow(df))))) {
    df <- cbind(row_id = rownames(df), df, stringsAsFactors = FALSE)
  }
  write.table(df, metadata_path, sep = "'"\\t\", quote = FALSE, row.names = FALSE, col.names = TRUE)
}
R
ls -l scripts/inspect_rds.R"

