import urllib.request, json
for repo in ['biocontainers/r-seurat','biocontainers/bioconductor-seurat','biocontainers/seurat']:
 url=f'https://quay.io/api/v1/repository/{repo}/tag/?limit=20&onlyActiveTags=true'
 req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
 try:
  data=json.load(urllib.request.urlopen(req,timeout=30))
  print('\\nREPO',repo)
  for t in data.get('tags',[])[:20]:
   print(t.get('name'), t.get('manifest_digest'), t.get('last_modified'))
 except Exception as e:
  print(repo, repr(e))
PY"

